using Health_Care_System.Entities; using Health_Care_System.PL.ViewModels; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc;
namespace Health_Care_System.PL.Controllers;
public class AccountController:Controller {private readonly UserManager<ApplicationUser> _userManager;private readonly SignInManager<ApplicationUser> _signInManager;public AccountController(UserManager<ApplicationUser> userManager,SignInManager<ApplicationUser> signInManager){_userManager=userManager;_signInManager=signInManager;}[HttpGet] public IActionResult Register()=>View();[HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Register(RegisterViewModel model){if(!ModelState.IsValid)return View(model);var user=new ApplicationUser{Name=model.Name,UserName=model.Email,Email=model.Email};var result=await _userManager.CreateAsync(user,model.Password);if(result.Succeeded){await _signInManager.SignInAsync(user,false);return RedirectToAction("Index","Home");}foreach(var e in result.Errors)ModelState.AddModelError("",e.Description);return View(model);}[HttpGet] public IActionResult Login(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View();}[HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel model,string? returnUrl=null){if(!ModelState.IsValid)return View(model);var result=await _signInManager.PasswordSignInAsync(model.Email,model.Password,model.RememberMe,false);if(result.Succeeded)return LocalRedirect(string.IsNullOrEmpty(returnUrl)?Url.Action("Index","Home")!:returnUrl);ModelState.AddModelError("","Invalid email or password.");return View(model);}[HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await _signInManager.SignOutAsync();return RedirectToAction("Index","Home");}}
